css:
#mag-slider-widget {
  position: relative;
  width: 100%;
  height: 450px;
  margin: 0 auto 2rem auto;
  background-color: var(--bs-tertiary-bg, #f8f9fa);
  border: 1px solid var(--border-color, #eaeaea);
  border-radius: var(--radius, 8px);
  overflow: hidden;
  box-shadow: 0 8px 25px rgba(0,0,0,0.05);
}
#mag-slider-loading {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--font-body, 'Inter', sans-serif);
  color: var(--mag-secondary, #6c757d);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  animation: fadePulse 2s infinite;
}
@keyframes fadePulse {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 1; }
}
.mag-slide {
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 100%;
  opacity: 0;
  transition: opacity 0.8s ease-in-out;
  display: block;
  text-decoration: none;
  z-index: 1;
}
.mag-slide.active-slide {
  opacity: 1;
  z-index: 5;
}
.mag-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.6) contrast(1.05);
  transition: transform 8s ease-out;
}
.mag-slide.active-slide img { transform: scale(1.04); }
.mag-slide-info {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  padding: 80px 40px 30px 40px;
  background: linear-gradient(to top, rgba(0,0,0,0.85) 0%, rgba(0,0,0,0) 100%);
  border-bottom: 4px solid var(--mag-primary, #0d6efd);
}
.mag-slide-title {
  font-family: var(--font-title, 'Playfair Display', serif);
  font-weight: 700;
  font-size: 2.2rem;
  line-height: 1.2;
  color: #ffffff;
  margin: 0 0 10px 0;
  text-shadow: 0 2px 5px rgba(0,0,0,0.4);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.mag-badge-news {
  display: inline-block;
  background: var(--mag-primary, #0d6efd);
  color: #ffffff;
  font-family: var(--font-body, 'Inter', sans-serif);
  font-weight: 700;
  font-size: 0.75rem;
  padding: 4px 12px;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-bottom: 12px;
  border-radius: 4px;
}
.mag-slider-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(255,255,255,0.15);
  color: #ffffff;
  border: 1px solid rgba(255,255,255,0.3);
  border-radius: 50%;
  width: 45px; height: 45px;
  cursor: pointer;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  transition: all 0.3s ease;
  backdrop-filter: blur(5px);
}
.mag-slider-nav:hover {
  background: var(--mag-primary, #0d6efd);
  border-color: var(--mag-primary, #0d6efd);
  transform: translateY(-50%) scale(1.05);
}
.mag-slider-prev { left: 20px; }
.mag-slider-next { right: 20px; }
@media (max-width: 768px) {
  #mag-slider-widget { height: 320px; }
  .mag-slide-title { font-size: 1.5rem; }
  .mag-slide-info { padding: 60px 20px 20px 20px; }
  .mag-slider-nav { width: 35px; height: 35px; font-size: 1rem; left: 10px; }
  .mag-slider-next { right: 10px; left: auto; }
}

javascript:
document.addEventListener('DOMContentLoaded', () => {
  const maxPosts = 5;
  const feedUrl = '/feeds/posts/default?alt=json&max-results=' + maxPosts;
  const track = document.getElementById('mag-slider-track');
  const loading = document.getElementById('mag-slider-loading');
  if (!track || !loading) return;

  fetch(feedUrl)
    .then(response => {
      if (!response.ok) throw new Error('Erro HTTP: ' + response.status);
      return response.json();
    })
    .then(data => {
      const posts = data.feed && data.feed.entry ? data.feed.entry : [];
      if (posts.length === 0) { loading.innerText = 'Nenhuma postagem encontrada.'; return; }

      let slidesHtml = '';
      posts.forEach((post, index) => {
        let postLink = post.link.find(l => l.rel === 'alternate')?.href || '#';
        let postTitle = post.title.$t;
        let imgUrl = 'https://placehold.co/1000x500/212529/6c757d?text=SEM+IMAGEM';

        if (post.media$thumbnail) {
          imgUrl = post.media$thumbnail.url;
        } else if (post.content && post.content.$t) {
          const tempDiv = document.createElement('div');
          tempDiv.innerHTML = post.content.$t;
          const firstImg = tempDiv.querySelector('img');
          if (firstImg) imgUrl = firstImg.src;
        }

        if (imgUrl.includes('bp.blogspot.com') || imgUrl.includes('googleusercontent.com')) {
          imgUrl = imgUrl.replace(/\/(s|w|h)\d+.*?(\/)/g, '/w1000-h500-c$2');
          imgUrl = imgUrl.replace(/=(s|w|h)\d+.*$/g, '=w1000-h500-c');
        }

        const activeClass = index === 0 ? 'active-slide' : '';
        slidesHtml += `<a href="${postLink}" class="mag-slide ${activeClass}"><img src="${imgUrl}" alt="${postTitle}" loading="lazy"><div class="mag-slide-info"><span class="mag-badge-news">Em Destaque</span><h3 class="mag-slide-title">${postTitle}</h3></div></a>`;
      });

      track.innerHTML = slidesHtml;
      loading.style.display = 'none';
      window.iniciarMagRotacao();
    })
    .catch(error => {
      console.error('Falha ao carregar o Slider:', error);
      loading.innerText = 'Falha ao carregar destaques.';
    });
});

let magSlideIndex = 0;
let magSlideInterval;

window.moveMagSlide = function(direcao) {
  const slides = document.querySelectorAll('#mag-slider-track .mag-slide');
  if (slides.length === 0) return;
  slides[magSlideIndex].classList.remove('active-slide');
  magSlideIndex += direcao;
  if (magSlideIndex >= slides.length) magSlideIndex = 0;
  if (magSlideIndex < 0) magSlideIndex = slides.length - 1;
  slides[magSlideIndex].classList.add('active-slide');
  window.resetMagRotacao();
};

window.iniciarMagRotacao = function() {
  magSlideInterval = setInterval(() => { window.moveMagSlide(1); }, 6000);
};

window.resetMagRotacao = function() {
  clearInterval(magSlideInterval);
  window.iniciarMagRotacao();
};
